<?php
session_start();
require_once 'db.php';
if (!isset($_SESSION['user_id'])) { header('Location: ../login.html'); exit; }
$userId=$_SESSION['user_id']; $nome=htmlspecialchars($_SESSION['nome']); $ruolo=$_SESSION['ruolo']; $classe=htmlspecialchars($_SESSION['classe']??''); $ruoloLabel=htmlspecialchars(ucfirst($ruolo));
$giorniIt=[1=>'Lunedi',2=>'Martedi',3=>'Mercoledi',4=>'Giovedi',5=>'Venerdi',6=>'Sabato',7=>'Domenica']; $oggiNum=(int)date('N');
if($ruolo==='studente'){
  $stmt=$pdo->prepare("SELECT stato,COUNT(*) tot FROM presenze WHERE studente_id=? GROUP BY stato");$stmt->execute([$userId]);$raw=$stmt->fetchAll();$totalePresenze=0;$presenti=0;foreach($raw as $r){$totalePresenze+=$r['tot'];if($r['stato']==='presente')$presenti+=$r['tot'];}$percentuale=$totalePresenze?round($presenti/$totalePresenze*100):0;
  $stmt=$pdo->prepare("SELECT p.data,m.nome materia,p.stato,p.note FROM presenze p LEFT JOIN materie m ON p.materia_id=m.id WHERE p.studente_id=? ORDER BY p.data DESC LIMIT 5");$stmt->execute([$userId]);$ultimePresenze=$stmt->fetchAll();
  $stmt=$pdo->prepare("SELECT AVG(voto) media FROM voti WHERE studente_id=?");$stmt->execute([$userId]);$m=$stmt->fetch()['media'];$media=$m!==null?number_format($m,1):'N/D';
  $stmt=$pdo->prepare("SELECT v.voto,v.tipo,v.data,m.nome materia FROM voti v JOIN materie m ON v.materia_id=m.id WHERE v.studente_id=? ORDER BY v.data DESC LIMIT 5");$stmt->execute([$userId]);$ultimiVoti=$stmt->fetchAll();
  $stmt=$pdo->prepare("SELECT ve.descrizione,ve.data,m.nome materia FROM verifiche ve JOIN materie m ON ve.materia_id=m.id WHERE ve.classe=? AND ve.data>=CURDATE() ORDER BY ve.data LIMIT 1");$stmt->execute([$classe]);$prossimaVerifica=$stmt->fetch();
  $stmt=$pdo->prepare("SELECT o.ora_inizio,o.ora_fine,m.nome materia FROM orario o JOIN materie m ON o.materia_id=m.id WHERE o.classe=? AND o.giorno_settimana=? ORDER BY o.ora_inizio");$stmt->execute([$classe,$oggiNum]);$orarioOggi=$stmt->fetchAll();
  $stmt=$pdo->prepare("SELECT COUNT(*) tot FROM messaggi WHERE destinatario_id=? AND letto=0");$stmt->execute([$userId]);$messaggiNonLetti=$stmt->fetch()['tot'];
  $stmt=$pdo->prepare("SELECT me.oggetto,me.created_at,me.letto,u.nome mittente FROM messaggi me LEFT JOIN utenti u ON me.mittente_id=u.id WHERE me.destinatario_id=? ORDER BY me.created_at DESC LIMIT 5");$stmt->execute([$userId]);$comunicazioni=$stmt->fetchAll();
}elseif($ruolo==='professore'){
  $stmt=$pdo->prepare("SELECT DISTINCT o.classe FROM orario o JOIN materie m ON o.materia_id=m.id WHERE m.professore_id=?");$stmt->execute([$userId]);$classiAssegnate=$stmt->fetchAll();
  $stmt=$pdo->prepare("SELECT id,nome FROM materie WHERE professore_id=?");$stmt->execute([$userId]);$materieInsegnate=$stmt->fetchAll();
  $stmt=$pdo->prepare("SELECT COUNT(*) tot FROM messaggi WHERE destinatario_id=? AND letto=0");$stmt->execute([$userId]);$messaggiNonLetti=$stmt->fetch()['tot'];
  $stmt=$pdo->prepare("SELECT o.classe,o.ora_inizio,o.ora_fine,m.nome materia FROM orario o JOIN materie m ON o.materia_id=m.id WHERE m.professore_id=? AND o.giorno_settimana=? ORDER BY o.ora_inizio");$stmt->execute([$userId,$oggiNum]);$orarioOggi=$stmt->fetchAll();
}
?>
<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard | School Digital Hub</title><style>:root{--bg:#0a0e17;--side:#0f1420;--text:#e6e9f0;--muted:#9aa4b8;--accent:#4f8cff;--ok:#3ddc97;--warn:#ffc107;--border:rgba(255,255,255,.09)}*{box-sizing:border-box}body{margin:0;display:flex;background:var(--bg);color:var(--text);font-family:system-ui,sans-serif;min-height:100vh}a{text-decoration:none;color:inherit}.side{width:250px;padding:24px 15px;background:var(--side);border-right:1px solid var(--border);position:fixed;height:100vh;display:flex;flex-direction:column}.brand{font-weight:800;font-size:1.2rem;margin:0 8px 25px;color:var(--accent)}.nav{display:block;padding:12px 14px;border-radius:9px;color:var(--muted);margin:3px 0}.nav.active,.nav:hover{background:#4f8cff22;color:var(--text)}.role{margin-top:auto;text-align:center;padding:9px;border-radius:9px;color:var(--ok);background:#3ddc9718}.main{margin-left:250px;flex:1}.top{height:66px;border-bottom:1px solid var(--border);padding:0 28px;display:flex;align-items:center;justify-content:space-between}.user{font-size:.9rem;color:var(--muted)}.content{padding:30px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:18px}.card{border:1px solid var(--border);border-radius:15px;padding:20px;background:#ffffff08}.num{font-size:1.9rem;font-weight:800;color:var(--accent);margin:9px 0}.muted{color:var(--muted);font-size:.9rem}h2.section{margin-top:34px;margin-bottom:14px;font-size:1.2rem}.table{width:100%;border-collapse:collapse}.table th,.table td{border-bottom:1px solid var(--border);padding:12px;text-align:left;font-size:.92rem}.table th{color:var(--muted);font-size:.78rem;text-transform:uppercase}.ok{color:var(--ok);font-weight:600}.warn{color:var(--warn);font-weight:600}.badge{background:#ff525222;color:#ff6b6b;font-size:.72rem;padding:2px 8px;border-radius:99px;margin-left:8px}.msg{padding:14px 0;border-bottom:1px solid var(--border)}.msg:last-child{border-bottom:0}.meta,.empty{font-size:.82rem;color:var(--muted)}@media(max-width:750px){.side{display:none}.main{margin:0}}</style></head><body><aside class="side"><div class="brand">School Digital Hub</div><a class="nav active" href="#">Panoramica</a><?php if($ruolo==='studente'): ?><a class="nav" href="#">Presenze</a><a class="nav" href="#">Orario</a><a class="nav" href="#">Voti</a><a class="nav" href="#">Messaggi<?php if($messaggiNonLetti>0): ?><span class="badge"><?= $messaggiNonLetti ?></span><?php endif ?></a><?php elseif($ruolo==='professore'): ?><a class="nav" href="#">Le mie classi</a><a class="nav" href="#">Orario</a><a class="nav" href="#">Registro voti</a><a class="nav" href="#">Messaggi<?php if($messaggiNonLetti>0): ?><span class="badge"><?= $messaggiNonLetti ?></span><?php endif ?></a><?php endif ?><a class="nav" href="../index.html">Home</a><div class="role">Ruolo: <?= $ruoloLabel ?></div></aside><main class="main"><header class="top"><h2>Panoramica</h2><div class="user"><?= $nome ?> · <?= $ruoloLabel ?><?= $classe?' '.$classe:'' ?> · <a href="logout.php">Esci</a></div></header><section class="content"><?php if($ruolo==='studente'): ?><div class="grid"><article class="card"><h3>Presenze</h3><div class="num"><?= $percentuale ?>%</div><p class="muted"><?= $presenti ?> presenze su <?= $totalePresenze ?></p></article><article class="card"><h3>Media voti</h3><div class="num"><?= $media ?></div><p class="muted">Valutazioni registrate</p></article><article class="card"><h3>Messaggi non letti</h3><div class="num"><?= $messaggiNonLetti ?></div><p class="muted">Nuove comunicazioni</p></article><article class="card"><h3>Prossima verifica</h3><?php if($prossimaVerifica): ?><div class="num"><?= htmlspecialchars($prossimaVerifica['materia']) ?></div><p class="muted"><?= htmlspecialchars($prossimaVerifica['descrizione']) ?> · <?= date('d/m/Y',strtotime($prossimaVerifica['data'])) ?></p><?php else: ?><p class="empty">Nessuna verifica programmata</p><?php endif ?></article></div><h2 class="section">Orario di oggi (<?= $giorniIt[$oggiNum] ?>)</h2><?php if($orarioOggi): ?><table class="table"><thead><tr><th>Ora</th><th>Materia</th></tr></thead><tbody><?php foreach($orarioOggi as $o): ?><tr><td><?= substr($o['ora_inizio'],0,5) ?> - <?= substr($o['ora_fine'],0,5) ?></td><td><?= htmlspecialchars($o['materia']) ?></td></tr><?php endforeach ?></tbody></table><?php else: ?><p class="empty">Nessuna lezione programmata per oggi.</p><?php endif ?><h2 class="section">Ultime presenze</h2><table class="table"><thead><tr><th>Data</th><th>Materia</th><th>Stato</th><th>Note</th></tr></thead><tbody><?php foreach($ultimePresenze as $p): ?><tr><td><?= date('d/m/Y',strtotime($p['data'])) ?></td><td><?= htmlspecialchars($p['materia']??'-') ?></td><td class="<?= $p['stato']==='presente'?'ok':'warn' ?>"><?= ucfirst($p['stato']) ?></td><td><?= htmlspecialchars($p['note']??'-') ?></td></tr><?php endforeach ?></tbody></table><h2 class="section">Ultimi voti</h2><table class="table"><thead><tr><th>Data</th><th>Materia</th><th>Tipo</th><th>Voto</th></tr></thead><tbody><?php foreach($ultimiVoti as $v): ?><tr><td><?= date('d/m/Y',strtotime($v['data'])) ?></td><td><?= htmlspecialchars($v['materia']) ?></td><td><?= htmlspecialchars($v['tipo']) ?></td><td class="<?= $v['voto']>=6?'ok':'warn' ?>"><?= $v['voto'] ?></td></tr><?php endforeach ?></tbody></table><h2 class="section">Ultime comunicazioni</h2><div class="card"><?php foreach($comunicazioni as $c): ?><div class="msg"><strong><?= htmlspecialchars($c['oggetto']) ?><?php if(!$c['letto']): ?><span class="badge">Nuovo</span><?php endif ?></strong><div class="meta"><?= htmlspecialchars($c['mittente']??'Segreteria') ?> · <?= date('d/m/Y',strtotime($c['created_at'])) ?></div></div><?php endforeach ?></div><?php elseif($ruolo==='professore'): ?><div class="grid"><article class="card"><h3>Classi assegnate</h3><div class="num"><?= count($classiAssegnate) ?></div><p class="muted"><?= implode(', ',array_column($classiAssegnate,'classe'))?:'Nessuna classe' ?></p></article><article class="card"><h3>Materie insegnate</h3><div class="num"><?= count($materieInsegnate) ?></div><p class="muted"><?= implode(', ',array_column($materieInsegnate,'nome'))?:'-' ?></p></article><article class="card"><h3>Messaggi non letti</h3><div class="num"><?= $messaggiNonLetti ?></div><p class="muted">Comunicazioni in arrivo</p></article></div><h2 class="section">Orario di oggi (<?= $giorniIt[$oggiNum] ?>)</h2><?php if($orarioOggi): ?><table class="table"><thead><tr><th>Ora</th><th>Classe</th><th>Materia</th></tr></thead><tbody><?php foreach($orarioOggi as $o): ?><tr><td><?= substr($o['ora_inizio'],0,5) ?> - <?= substr($o['ora_fine'],0,5) ?></td><td><?= htmlspecialchars($o['classe']) ?></td><td><?= htmlspecialchars($o['materia']) ?></td></tr><?php endforeach ?></tbody></table><?php else: ?><p class="empty">Nessuna lezione programmata per oggi.</p><?php endif ?><?php else: ?><p class="empty">Ruolo non gestito in questa versione.</p><?php endif ?></section></main></body></html>